namespace speed {
namespace {
void cue(RunRuntime &r,const TechniqueState &t,const char *name) {const auto &e=r.state.enemies[t.actor.slot];godot::Dictionary p;p["id"]=e.id;p["technique"]=t.definition;p["cue"]=name;p["position"]=e.pos;p["angle"]=e.facing;const auto *body=PhaseController::find(r,t.actor);p["world_time"]=body?body->clock:r.state.world_time;FrameBuilder::append(r,"canis_cue",p);}
void clear_warning(RunRuntime &r,TechniqueState &t) {auto &v=std::get<CanisCommandState>(t.detail);for (auto actor:v.warned) if (auto *order=GroupSystem::order(r.state,actor)) {order->warning=false;order->warning_until=0;}v.warned.clear();}
}
bool CanisCommand::ready(const RunRuntime &r,EnemyHandle actor,uint32_t definition) {const auto *b=PhaseController::find(r,actor);if (!b || b->canis.barking || b->canis.calling || !r.state.enemy_handles.contains(actor) || r.state.enemies[actor.slot].dead) return false;const auto v=std::find_if(r.content->canis_commands.begin(),r.content->canis_commands.end(),[&](const auto &p){return p.technique==definition;});return v!=r.content->canis_commands.end() && b->canis.led.size()>=v->min_hounds;}
void CanisCommand::begin(RunRuntime &r,TechniqueState &t) {t.detail=CanisCommandState{};t.aim=r.state.enemy_aim;t.previous_ship=r.state.ship_pos;auto &e=r.state.enemies[t.actor.slot];e.vel={};cue(r,t,"telegraph");}
void CanisCommand::step(RunRuntime &r,TechniqueState &t,double dt) {auto &e=r.state.enemies[t.actor.slot];e.vel={};const auto &p=r.content->boss_techniques[t.definition-1];if (t.stage==TechniqueStage::Recovery) {t.remaining=std::max(0.0,t.remaining-dt);if (t.remaining<=0) t.stage=TechniqueStage::Finished;return;}if (t.stage==TechniqueStage::Windup) {const auto *fx=CanisRoar::settings(*r.content,t.definition);auto &state=std::get<CanisCommandState>(t.detail);auto *body=PhaseController::find(r,t.actor);if (fx && body && !state.warning_started) {const double cue=p.warn-std::min(p.warn*.65,.32);const double lives[]={0,.24,.36,.52};const double warning=cue+lives[fx->level]*fx->roar_time*fx->timing+fx->order_wait;if (body->clock-t.started_at>=warning) {state.warning_started=true;const double until=r.state.world_time+std::max(0.0,warning+fx->hound_warn-(body->clock-t.started_at));for (const auto &v:body->canis.led) if (!CanisHowl::in_ring(*body,v.actor) && GroupSystem::mark(r.state,v.actor,until)) state.warned.push_back(v.actor);}}}if (t.stage==TechniqueStage::Windup && !t.locked && p.track_during_warn) {t.aim=TrackingPolicy{r.state.draw.tracing,e.held,r.state.enemy_handles.contains(e.pump_owner)}.target(e.pos,e.facing,r.state.enemy_aim);e.facing+=std::clamp(angle_difference((t.aim-e.pos).angle()-e.facing),-r.content->bosses[p.boss-1].turn*dt,r.content->bosses[p.boss-1].turn*dt);}if (t.stage==TechniqueStage::Active) if (auto *b=PhaseController::find(r,t.actor)) {CanisHoundLunge::step(r,*b,t.id);t.hit=CanisHoundLunge::action_hit(*b,t.id);}}
void CanisCommand::command(RunRuntime &r,TechniqueState &t,TechniqueCommand command) {const auto &p=r.content->boss_techniques[t.definition-1];auto *b=PhaseController::find(r,t.actor);if (!b) {t.stage=TechniqueStage::Failed;return;}if (command==TechniqueCommand::LaunchStrike && t.stage==TechniqueStage::Windup) {clear_warning(r,t);t.stage=TechniqueStage::Active;t.hit=false;const auto &v=*std::find_if(r.content->canis_commands.begin(),r.content->canis_commands.end(),[&](const auto &v){return v.technique==t.definition;});HoundLungeSettings settings;settings.speed=v.lunge_speed;settings.duration=v.lunge_time;settings.damage=p.damage;settings.grace=0.05;settings.sweep=false;settings.shared_hit=true;settings.overwrite_velocity=false;settings.quiet=false;settings.release_on_cancel=false;settings.release_on_end=false;settings.defer_first_contact=true;settings.track_aim=false;settings.technique=r.state.bosses->handles.at(uint32_t(&t-r.state.bosses->techniques.data()));settings.source_technique=t.definition;for (const auto &hound:b->canis.led) if (!CanisHowl::in_ring(*b,hound.actor)) CanisHoundLunge::begin(r,*b,hound.actor,t.id,settings);cue(r,t,"command");}else if (command==TechniqueCommand::EndStrike && (t.stage==TechniqueStage::Active || t.stage==TechniqueStage::Windup)) {clear_warning(r,t);t.stage=TechniqueStage::Recovery;t.remaining=p.recover;t.locked=false;r.state.enemies[t.actor.slot].vel={};cue(r,t,"recovery_started");}}
void CanisCommand::cancel(RunRuntime &r,TechniqueState &t) {clear_warning(r,t);if (auto *b=PhaseController::find(r,t.actor)) CanisHoundLunge::end_action(r,*b,t.id,true);}
bool CanisCommand::validate(const TechniqueState &t) {return std::holds_alternative<CanisCommandState>(t.detail);}
}
